def loop_start_depot(fuel, burn):
    if sum(fuel) < sum(burn):
        return -1
    start, tank = 0, 0
    for i in range(len(fuel)):
        tank += fuel[i] - burn[i]
        if tank < 0:
            start, tank = i + 1, 0
    return start
